    scheduler.io.dcacheWritebackRequestDirty &&
    scheduler.io.dcacheWritebackRequestPacketTracked &&
    scheduler.io.dcacheWritebackRequestPacketSeq =/= 0.U &&
    scheduler.io.dcacheWritebackRequestPacketSeq > l2SafeWatermark
